-- UPDATE MODUL PENELITIAN ENTROPY + TOPSIS 2024
-- KHUSUS DATABASE EXISTING `aplikasiremmitance`: import melalui phpMyAdmin tab SQL.
-- WAJIB BACKUP DB sebelum menjalankan. TIDAK MEMBUAT ULANG tabel operasional.
-- 4 alternatif, 6 benefit, P1: 2024-09-01...2024-10-31, P2: 2024-11-01...2024-12-31.
-- Replaces prior analyses and research SPK sources ONLY; retains users, invoices, transactions, etc.
-- Entire patch executes as one transaction (InnoDB); FK-safe deletion order.
START TRANSACTION;
DELETE FROM `spk_results`;
DELETE FROM `spk_weights`;
DELETE FROM `spk_runs`;
DELETE FROM `spk_assessments`;
DELETE FROM `spk_records`;
DELETE FROM `spk_sources`;
-- Modul penelitian sekarang hanya memakai dua sumber olahan tahun 2024.
DELETE FROM `spk_subcriteria`;
DELETE FROM `spk_criteria`;
DELETE FROM `spk_alternatives`;
-- Legacy analysis tables (if used in older app) are also obsolete for this final research run.
DELETE FROM `analysis_results`;
DELETE FROM `analysis_weights`;
DELETE FROM `analysis_runs`;









COMMIT;
-- VALIDASI (jalankan setelah COMMIT):
SELECT source_id, event_type, COUNT(*) AS jumlah FROM spk_records GROUP BY source_id,event_type;
SELECT criterion_code, weight_value FROM spk_weights WHERE run_id=1 ORDER BY criterion_code;
SELECT rank_position, alternative_name, preference_value FROM spk_results WHERE run_id=1 ORDER BY rank_position;
